        $invoke={ Test-PraRawCapture -Context $global:PraGate.Context -LiteralPath $path -Records @(@{ObjectGuid=$id}) -RawFormat '' }
        if ($Accept) { $checked=& $invoke; $checked.Count | Should -Be 1; $checked.ObjectGuids[0] | Should -BeExactly $id }
